-- Align the Book 3 lesson map with the verified source table of contents.
begin;
update public.rules as r set title=v.title, content=v.content, summary=v.summary from (values
('1','الإِعْرَابُ وَعَلَامَاتُهُ (Падежные окончания и их признаки)','<p><strong>Суть правила.</strong> Урок объединяет изменяемые и неизменяемые имена, основные и второстепенные показатели падежа, а также скрытое окончание. Падеж определяют по роли слова и его типу: обычное имя, двойственное число, правильное множественное или одно из особых имён.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ المُدَرِّسُ</strong> — Пришёл преподаватель..</li><li><strong dir="rtl" lang="ar">سَأَلْتُ المُدَرِّسَ</strong> — Я спросил преподавателя..</li><li><strong dir="rtl" lang="ar">سَلَّمْتُ عَلَى المُدَرِّسِ</strong> — Я поприветствовал преподавателя..</li></ol>','Урок объединяет изменяемые и неизменяемые имена, основные и второстепенные показатели падежа, а также скрытое окончание. Падеж определяют по роли слова и его типу: обычное имя, двойственное число, правильное множественное или одно из особых имён.'),
('2','الفِعْلُ الثُّلَاثِيُّ المُجَرَّدُ وَالمَزِيدُ (Простой и расширенный трёхбуквенный глагол)','<p><strong>Суть правила.</strong> Трёхбуквенный корень может быть простым или получать добавочные буквы. В уроке закрепляются модели прошедшего и настоящего времени, а также действительный и страдательный залог. Сначала найдите корень, затем отличайте его от добавочных букв модели.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ</strong> — Студент написал урок..</li><li><strong dir="rtl" lang="ar">كُتِبَ الدَّرْسُ</strong> — Урок был написан..</li><li><strong dir="rtl" lang="ar">اِسْتَخْرَجَ الطَّالِبُ الفَائِدَةَ</strong> — Студент извлёк пользу..</li></ol>','Трёхбуквенный корень может быть простым или получать добавочные буквы. В уроке закрепляются модели прошедшего и настоящего времени, а также действительный и страдательный залог. Сначала найдите корень, затем отличайте его от добавочных букв модели.'),
('3','هَاءُ الضَّمِيرِ وَالنِّسْبَةُ (Местоименная ха и относительное прилагательное)','<p><strong>Суть правила.</strong> Слитная ха указывает на владельца или объект: كِتَابُهُ — «его книга», رَأَيْتُهُ — «я увидел его». Нисба образует относительное прилагательное с يّ: مِصْرِيّ — «египетский». Важно не смешивать местоименную ха с коренной буквой слова.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا كِتَابُهُ</strong> — Это его книга..</li><li><strong dir="rtl" lang="ar">رَأَيْتُهُ فِي الفَصْلِ</strong> — Я увидел его в классе..</li><li><strong dir="rtl" lang="ar">هُوَ طَالِبٌ مِصْرِيٌّ</strong> — Он египетский студент..</li></ol>','Слитная ха указывает на владельца или объект: كِتَابُهُ — «его книга», رَأَيْتُهُ — «я увидел его». Нисба образует относительное прилагательное с يّ: مِصْرِيّ — «египетский». Важно не смешивать местоименную ха с коренной буквой слова.'),
('4','اِسْمُ الفَاعِلِ وَاِسْمُ المَفْعُولِ مِنَ الصَّحِيحِ (Действительное и страдательное причастия от правильного глагола)','<p><strong>Суть правила.</strong> От правильного трёхбуквенного глагола действительное причастие обычно имеет модель فَاعِل, а страдательное — مَفْعُول. Они могут работать как прилагательные или как имена, сохраняя связь с действием.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا طَالِبٌ كَاتِبٌ</strong> — Это пишущий студент..</li><li><strong dir="rtl" lang="ar">هَذَا دَرْسٌ مَكْتُوبٌ</strong> — Это написанный урок..</li><li><strong dir="rtl" lang="ar">المُسْلِمُ شَاكِرٌ لِرَبِّهِ</strong> — Мусульманин благодарен своему Господу..</li></ol>','От правильного трёхбуквенного глагола действительное причастие обычно имеет модель فَاعِل, а страдательное — مَفْعُول. Они могут работать как прилагательные или как имена, сохраняя связь с действием.'),
('5','اِسْمُ الفَاعِلِ وَاِسْمُ المَفْعُولِ مِنَ المُعْتَلِّ (Причастия от слабого глагола)','<p><strong>Суть правила.</strong> У слабых глаголов причастия сохраняют модель, но слабая буква может меняться или выпадать. Например: قَالَ — قَائِل, دَعَا — دَاعٍ, قَالَ — مَقُول. Форму лучше учить вместе с исходным глаголом.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا رَجُلٌ قَائِلٌ الحَقَّ</strong> — Это человек, говорящий правду..</li><li><strong dir="rtl" lang="ar">هُوَ دَاعٍ إِلَى الخَيْرِ</strong> — Он призывающий к добру..</li><li><strong dir="rtl" lang="ar">هَذَا قَوْلٌ مَقُولٌ</strong> — Это сказанное высказывание..</li></ol>','У слабых глаголов причастия сохраняют модель, но слабая буква может меняться или выпадать. Например: قَالَ — قَائِل, دَعَا — دَاعٍ, قَالَ — مَقُول. Форму лучше учить вместе с исходным глаголом.'),
('6','اِسْمَا الزَّمَانِ وَالمَكَانِ (Имя времени и места)','<p><strong>Суть правила.</strong> Эти производные имена называют время или место действия. От трёхбуквенного глагола часто встречаются модели مَفْعِل и مَفْعَل; у расширенных глаголов обычно используется форма настоящего времени с мимом. Значение подтверждается контекстом.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">المَسْجِدُ مَكَانُ الصَّلَاةِ</strong> — Мечеть — место молитвы..</li><li><strong dir="rtl" lang="ar">هَذَا مَوْعِدُ الدَّرْسِ</strong> — Это время урока..</li><li><strong dir="rtl" lang="ar">ذَهَبْتُ إِلَى المَكْتَبِ</strong> — Я пошёл в кабинет..</li></ol>','Эти производные имена называют время или место действия. От трёхбуквенного глагола часто встречаются модели مَفْعِل и مَفْعَل; у расширенных глаголов обычно используется форма настоящего времени с мимом. Значение подтверждается контекстом.'),
('7','اِسْمُ الآلَةِ (Имя орудия)','<p><strong>Суть правила.</strong> Имя орудия называет предмет, которым выполняют действие. Частые модели: مِفْعَال, مِفْعَل и مِفْعَلَة. Их лучше запоминать как словарные формы, потому что не у каждого глагола есть регулярно образуемое имя орудия.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">فَتَحْتُ البَابَ بِالمِفْتَاحِ</strong> — Я открыл дверь ключом..</li><li><strong dir="rtl" lang="ar">كَتَبْتُ بِالقَلَمِ</strong> — Я написал ручкой..</li><li><strong dir="rtl" lang="ar">هَذِهِ مِكْنَسَةٌ</strong> — Это метла..</li></ol>','Имя орудия называет предмет, которым выполняют действие. Частые модели: مِفْعَال, مِفْعَل и مِفْعَلَة. Их лучше запоминать как словарные формы, потому что не у каждого глагола есть регулярно образуемое имя орудия.'),
('8','المَعْرِفَةُ وَالنَّكِرَةُ (Определённое и неопределённое имя)','<p><strong>Суть правила.</strong> Неопределённое имя называет предмет вообще, а определённое указывает на известный или конкретный предмет. Определённость возникает через артикль ال, имя собственное, местоимение, указательное слово, относительное имя или идафу к определённому слову.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ رَجُلٌ</strong> — Пришёл какой-то мужчина..</li><li><strong dir="rtl" lang="ar">جَاءَ الرَّجُلُ</strong> — Пришёл этот конкретный мужчина..</li><li><strong dir="rtl" lang="ar">هَذَا كِتَابُ الطَّالِبِ</strong> — Это книга студента..</li></ol>','Неопределённое имя называет предмет вообще, а определённое указывает на известный или конкретный предмет. Определённость возникает через артикль ال, имя собственное, местоимение, указательное слово, относительное имя или идафу к определённому слову.'),
('9','حَذْفُ نُونِ المُثَنَّى وَالجَمْعِ عِنْدَ الإِضَافَةِ (Идафа и удаление нуна)','<p><strong>Суть правила.</strong> В идафе у двойственного числа и правильного мужского множественного удаляется нун: كِتَابَا الطَّالِبِ и مُسْلِمُو البَلَدِ. Первое слово получает падеж по своей роли, а второе всегда стоит в родительном падеже.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا كِتَابُ الطَّالِبِ</strong> — Это книга студента..</li><li><strong dir="rtl" lang="ar">جَاءَ مُسْلِمُو البَلَدِ</strong> — Пришли мусульмане страны..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ كِتَابَيْ الطَّالِبِ</strong> — Я увидел две книги студента..</li></ol>','В идафе у двойственного числа и правильного мужского множественного удаляется нун: كِتَابَا الطَّالِبِ и مُسْلِمُو البَلَدِ. Первое слово получает падеж по своей роли, а второе всегда стоит в родительном падеже.'),
('10','الجُمْلَةُ الاِسْمِيَّةُ وَالفِعْلِيَّةُ وَالمَصْدَرُ المُؤَوَّلُ (Именное и глагольное предложение; развёрнутый масдар)','<p><strong>Суть правила.</strong> Именное предложение обычно начинается с имени, а глагольное — с глагола. Сочетание أَنْ с настоящим глаголом может занимать место масдара: أُرِيدُ أَنْ أَتَعَلَّمَ — «я хочу учиться». Это помогает увидеть роль целого оборота в предложении.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">العِلْمُ نَافِعٌ</strong> — Знание полезно..</li><li><strong dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ</strong> — Студент написал урок..</li><li><strong dir="rtl" lang="ar">أُرِيدُ أَنْ أَتَعَلَّمَ</strong> — Я хочу учиться..</li></ol>','Именное предложение обычно начинается с имени, а глагольное — с глагола. Сочетание أَنْ с настоящим глаголом может занимать место масдара: أُرِيدُ أَنْ أَتَعَلَّمَ — «я хочу учиться». Это помогает увидеть роль целого оборота в предложении.'),
('11','المُبْتَدَأُ وَالخَبَرُ (Подлежащее и сказуемое)','<p><strong>Суть правила.</strong> Мубтада — то, о чём говорится, хабар — сообщение о нём. Оба обычно стоят в именительном падеже. Хабар может быть отдельным словом, предложением или предложной конструкцией.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">العِلْمُ نَافِعٌ</strong> — Знание полезно..</li><li><strong dir="rtl" lang="ar">الطَّالِبُ فِي الفَصْلِ</strong> — Студент в классе..</li><li><strong dir="rtl" lang="ar">أَبِي مُدَرِّسٌ</strong> — Мой отец преподаватель..</li></ol>','Мубтада — то, о чём говорится, хабар — сообщение о нём. Оба обычно стоят в именительном падеже. Хабар может быть отдельным словом, предложением или предложной конструкцией.'),
('12','المَفْعُولُ فِيهِ (Обстоятельство времени и места)','<p><strong>Суть правила.</strong> Маф‘уль фихи называет время или место, в пределах которого происходит действие. Обычно он отвечает на «когда?» или «где?» и стоит в винительном падеже, если не введён предлогом.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">سَافَرْتُ لَيْلًا</strong> — Я путешествовал ночью..</li><li><strong dir="rtl" lang="ar">جَلَسْتُ أَمَامَ المُدَرِّسِ</strong> — Я сел перед преподавателем..</li><li><strong dir="rtl" lang="ar">دَرَسْتُ يَوْمَ الجُمُعَةِ</strong> — Я учился в пятницу..</li></ol>','Маф‘уль фихи называет время или место, в пределах которого происходит действие. Обычно он отвечает на «когда?» или «где?» и стоит в винительном падеже, если не введён предлогом.'),
('13','لَامُ الأَمْرِ وَالجَزْمُ (Лам приказа и усечение)','<p><strong>Суть правила.</strong> Лам приказа ставится перед настоящим глаголом и требует усечения: لِيَكْتُبْ. Усечение также появляется после частиц لَمْ и لَمَّА. Отличайте лам приказа от лама цели, который приводит глагол к винительному состоянию.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">لِيَكْتُبْ الطَّالِبُ الدَّرْسَ</strong> — Пусть студент запишет урок..</li><li><strong dir="rtl" lang="ar">لَمْ يَذْهَبْ خَالِدٌ</strong> — Халид не пошёл..</li><li><strong dir="rtl" lang="ar">فَلْيَقُلْ خَيْرًا</strong> — Пусть он говорит доброе..</li></ol>','Лам приказа ставится перед настоящим глаголом и требует усечения: لِيَكْتُبْ. Усечение также появляется после частиц لَمْ и لَمَّА. Отличайте лам приказа от лама цели, который приводит глагол к винительному состоянию.'),
('14','أَدَوَاتُ الشَّرْطِ غَيْرُ الجَازِمَةِ (Неусекающие условные частицы)','<p><strong>Суть правила.</strong> Неусекающие условные частицы, например إِذَا, связывают условие с его результатом, но не меняют окончание настоящего глагола. Они часто описывают ожидаемое или повторяющееся событие. Смысл условия сохраняется, а форма глагола остаётся обычной.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">إِذَا جَاءَ المُدَرِّسُ قُمْنَا</strong> — Когда придёт преподаватель, мы встанем..</li><li><strong dir="rtl" lang="ar">إِذَا تَدْرُسُ تَفْهَمُ</strong> — Когда ты учишься, ты понимаешь..</li><li><strong dir="rtl" lang="ar">كُلَّمَا جَاءَ ضَيْفٌ أَكْرَمْنَاهُ</strong> — Когда бы ни пришёл гость, мы оказываем ему честь..</li></ol>','Неусекающие условные частицы, например إِذَا, связывают условие с его результатом, но не меняют окончание настоящего глагола. Они часто описывают ожидаемое или повторяющееся событие. Смысл условия сохраняется, а форма глагола остаётся обычной.'),
('15','أَدَوَاتُ الشَّرْطِ الجَازِمَةُ (Усекающие условные частицы)','<p><strong>Суть правила.</strong> После частиц إِنْ, مَنْ, مَا, مَهْمَا обычно усечены и глагол условия, и его ответ. Если ответ нельзя поставить прямо после условия, он соединяется с фа. Сначала найдите две части условной конструкции.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">إِنْ تَجْتَهِدْ تَنْجَحْ</strong> — Если будешь стараться, преуспеешь..</li><li><strong dir="rtl" lang="ar">مَنْ يَصْدُقْ يُحْتَرَمْ</strong> — Кто говорит правду, того уважают..</li><li><strong dir="rtl" lang="ar">مَهْمَا تَفْعَلْ تُجْزَ بِهِ</strong> — Что бы ты ни сделал, за это получишь воздаяние..</li></ol>','После частиц إِنْ, مَنْ, مَا, مَهْمَا обычно усечены и глагол условия, и его ответ. Если ответ нельзя поставить прямо после условия, он соединяется с фа. Сначала найдите две части условной конструкции.'),
('16','الأَفْعَالُ الثُّلَاثِيَّةُ وَجُمُوعُ التَّكْسِيرِ (Модели простого глагола и ломаное множественное)','<p><strong>Суть правила.</strong> У простого трёхбуквенного глагола несколько моделей настоящего времени, например فَعَلَ يَفْعُلُ и فَعَلَ يَفْعِلُ. Ломаное множественное меняет внутренний рисунок слова, поэтому его учат вместе с единственным числом.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">كَتَبَ يَكْتُبُ</strong> — Он написал — он пишет..</li><li><strong dir="rtl" lang="ar">جَلَسَ يَجْلِسُ</strong> — Он сел — он сидит..</li><li><strong dir="rtl" lang="ar">كِتَابٌ كُتُبٌ</strong> — Книга — книги..</li></ol>','У простого трёхбуквенного глагола несколько моделей настоящего времени, например فَعَلَ يَفْعُلُ и فَعَلَ يَفْعِلُ. Ломаное множественное меняет внутренний рисунок слова, поэтому его учат вместе с единственным числом.'),
('17','البَابُ الرَّابِعُ وَالفِعْلُ المُتَعَدِّي إِلَى مَفْعُولَيْنِ (Четвёртая порода и глаголы с двумя дополнениями)','<p><strong>Суть правила.</strong> Четвёртая порода имеет модель أَفْعَلَ и часто придаёт причинный смысл: أَخْرَجَ — «вывел». Некоторые глаголы требуют двух дополнений, например أَعْطَى: «дать кому-то что-то». В разборе называйте оба дополнения отдельно.</p><p><strong>Как применять.</strong> Найдите конструкцию, определите её роль и проверьте форму каждого ключевого слова.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">أَخْرَجَ المُدَرِّسُ الطَّالِبَ</strong> — Преподаватель вывел студента..</li><li><strong dir="rtl" lang="ar">أَعْطَيْتُ الطَّالِبَ كِتَابًا</strong> — Я дал студенту книгу..</li><li><strong dir="rtl" lang="ar">أَرَيْتُهُ البَيْتَ</strong> — Я показал ему дом..</li></ol>','Четвёртая порода имеет модель أَفْعَلَ и часто придаёт причинный смысл: أَخْرَجَ — «вывел». Некоторые глаголы требуют двух дополнений, например أَعْطَى: «дать кому-то что-то». В разборе называйте оба дополнения отдельно.')
) as v(lesson_number,title,content,summary) where r.course_name='Мединский курс (Том 3)' and r.lesson_number=v.lesson_number;
commit;
